  app: AtlasApp
  threadId: ThreadId
  store: ConversationStore
}): void {
  const { app, threadId, store } = args

  useEffect(() => {
    let held = app.executionLocation.of(threadId)
    return app.executionLocation.subscribe(() => {
      const next = app.executionLocation.of(threadId)
      if (next === held) return
      held = next
      store.republish()
